WITH filtered AS (SELECT id, name, country, city, segment, signup_date, credit_limit, age, INITCAP(TRIM(country)) AS country_title, COALESCE(city, 'DIRECT') AS city_filled FROM customers WHERE signup_date > DATE '2023-10-08') SELECT CASE WHEN age >= 58 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_tier, MAX(credit_limit) AS max_credit_limit, COUNT_IF(country = 'DE') AS de_events, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, STDDEV_SAMP(age) AS age_stddev, COUNT(CASE WHEN segment = 'Corporate' THEN 1 END) AS corporate_count FROM filtered GROUP BY 1;
